/**
 * Builds src/iconify-bundle/icons-himma.js: only the icons Himma's own code uses, so every page
 * does not have to load the whole tabler set (icons-bundle-react.js, ~1 MB, now demo pages only).
 *
 * Run after adding an icon:  npm run build:icons
 * An icon missing from the bundle still shows (Iconify fetches it online), just more slowly.
 */
const { promises: fs } = require('fs')
const path = require('path')
const { getIcons } = require('@iconify/utils')

const root = path.resolve(__dirname, '../..')

// Himma code; the Vuexy demo pages are left out on purpose.
const sources = [
  'src/@core',
  'src/layouts',
  'src/navigation',
  'src/configs',
  'src/context',
  'src/hooks',
  'src/views/admin',
  'src/pages/admin',
  'src/pages/billing',
  'src/pages/login',
  'src/pages/forgot-password',
  'src/pages/register',
  'src/pages/401.js',
  'src/pages/404.js',
  'src/pages/500.js'
]

const sets = {
  tabler: require.resolve('@iconify/json/json/tabler.json'),
  mdi: require.resolve('@iconify/json/json/mdi.json')
}

const target = path.join(root, 'src/iconify-bundle/icons-himma.js')

async function listFiles(entry) {
  const full = path.join(root, entry)
  const stat = await fs.stat(full).catch(() => null)
  if (!stat) return []
  if (stat.isFile()) return [full]

  const files = []
  for (const name of await fs.readdir(full)) {
    files.push(...(await listFiles(path.join(entry, name))))
  }

  return files.filter(file => /\.(js|jsx)$/.test(file))
}

;(async function () {
  const used = Object.fromEntries(Object.keys(sets).map(prefix => [prefix, new Set()]))
  const pattern = new RegExp(`['"\`](${Object.keys(sets).join('|')}):([a-z0-9-]+)['"\`]`, 'g')

  for (const entry of sources) {
    for (const file of await listFiles(entry)) {
      const text = await fs.readFile(file, 'utf8')
      for (const match of text.matchAll(pattern)) used[match[1]].add(match[2])
    }
  }

  let bundle =
    "// Generated by src/iconify-bundle/bundle-himma-icons.js — do not edit.\nimport { addCollection } from '@iconify/react'\n\n"
  for (const [prefix, names] of Object.entries(used)) {
    if (!names.size) continue
    const set = JSON.parse(await fs.readFile(sets[prefix], 'utf8'))
    const subset = getIcons(set, [...names].sort())
    if (!subset) continue
    bundle += `addCollection(${JSON.stringify(subset)})\n`
    console.log(`${prefix}: ${Object.keys(subset.icons).length} icons`)
  }

  await fs.writeFile(target, bundle, 'utf8')
  console.log(`Saved ${path.relative(root, target)} (${Math.round(bundle.length / 1024)} KB)`)
})().catch(err => {
  console.error(err)
  process.exit(1)
})
